(()=>{
 const $=id=>document.getElementById(id), key='specialEducationParentPinV1';let role='locked',next='guardian',busy=false;
 const protectedScreens=new Set(['guardian','settings','plan','profile','avatar','intro','assessment','method']);
 const record=()=>{try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}};
 const hash=async(pin,salt)=>{const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(salt),iterations:150000,hash:'SHA-256'},material,256);return Array.from(new Uint8Array(bits),v=>v.toString(16).padStart(2,'0')).join('');};
 function sync(){$('panelButton').hidden=role!=='guardian';['editAssessment','editMethod'].forEach(id=>$(id).hidden=role!=='guardian');$('settingsButton').textContent=role==='guardian'?'⚙️ Ayarlar':'🔒 Uygulamacı';}
 function lock(){role='locked';stopPreviews();window.LocalMicrophone?.disable();speechSynthesis?.cancel();AppEntry.resetHistory();sync();AppEntry.show('welcome',false);}
 function open(target='guardian'){next=target;const saved=record();$('pinTitle').textContent=saved?'Uygulamacı girişi':'Uygulamacı PIN’i oluştur';$('pinHelp').textContent=saved?'Bu uygulama için belirlediğiniz PIN’i girin.':'Telefon şifresinden ayrı, 6 haneli bir PIN belirleyin. PIN bu tarayıcıda saklanır; unutursanız uygulama verilerini sıfırlamak gerekir.';$('pinConfirmLabel').hidden=!!saved;$('parentPinConfirm').required=!saved;$('pinForm').reset();$('pinMessage').textContent='';AppEntry.show('pin');$('parentPin').focus();}
 function child(){if(!record()||!AppEntry.ready()){$('guardianNote').textContent=$('entryNote').textContent='Önce bir yetişkin uygulamacı girişinden öğrenci ve öğretim yöntemini hazırlamalı.';return;}role='child';AppEntry.resetHistory();sync();window.LocalMicrophone?.ensure().catch(()=>{});AppEntry.platform(false);}
 window.ParentGate={role:()=>role,open,stopPreviews,allow:name=>name==='welcome'||name==='pin'||(role==='guardian')||(role==='child'&&!protectedScreens.has(name))};
 $('panelButton').onclick=()=>AppEntry.show('guardian');$('guardianEntry').onclick=()=>open();$('childEntry').onclick=child;$('pinCancel').onclick=lock;$('guardianLock').onclick=lock;$('guardianChild').onclick=child;$('guardianActivities').onclick=()=>AppEntry.platform();
 document.querySelectorAll('[data-guardian-screen]').forEach(b=>b.onclick=()=>AppEntry.show(b.dataset.guardianScreen));$('guardianAssessment').onclick=()=>$('editAssessment').click();$('guardianMethod').onclick=()=>$('editMethod').click();
 $('pinForm').onsubmit=async event=>{event.preventDefault();if(busy)return;const pin=$('parentPin').value,saved=record();if(!/^\d{6}$/.test(pin))return;if(saved?.blockedUntil>Date.now()){$('pinMessage').textContent='Çok fazla deneme yapıldı. Biraz bekleyip tekrar deneyin.';return;}if(!saved&&pin!==$('parentPinConfirm').value){$('pinMessage').textContent='İki PIN aynı olmalı.';return;}busy=true;$('pinSubmit').disabled=true;try{if(!saved){const salt=Array.from(crypto.getRandomValues(new Uint8Array(16)));localStorage.setItem(key,JSON.stringify({salt,digest:await hash(pin,salt),failures:0}));}else if(await hash(pin,saved.salt)!==saved.digest){saved.failures=(saved.failures||0)+1;if(saved.failures>=5){saved.blockedUntil=Date.now()+30000;saved.failures=0;}localStorage.setItem(key,JSON.stringify(saved));$('pinMessage').textContent='PIN doğru değil. Tekrar deneyin.';$('parentPin').value='';return;}else{saved.failures=0;saved.blockedUntil=0;localStorage.setItem(key,JSON.stringify(saved));}role='guardian';sync();$('pinForm').reset();AppEntry.resetHistory();AppEntry.show(next==='guardian'?'guardian':next,false);}catch{$('pinMessage').textContent='PIN kaydedilemedi. Tarayıcı depolaması ve güvenli bağlantıyı kontrol edin.';}finally{busy=false;$('pinSubmit').disabled=false;}};
 const tracks=[['playful','Playful Children · AudioCoffee','music/playful-children.mp3','2:20'],['fun-game','Fun Game · REDproductions','music/fun-game.mp3','2:20'],['riley','Life of Riley · Kevin MacLeod','music/life-of-riley.mp3','3:08'],['original','Mevcut müzik','dijital-ozel-egitim-menu-muzigi.mp3',''],['steps','Neşeli adımlar','music/steps.wav','1:30'],['garden','Sakin Bahçe · piyano valsi','music/garden.wav','1:45'],['play','Oyun Zamanı · ritmik telli çalgılar','music/play.wav','2:00']];
 function stopPreviews(){document.querySelectorAll('#musicChoices audio').forEach(a=>a.pause());}
 const music=$('backgroundMusic');let selected=localStorage.getItem('specialEducationMusic')||'original';if(!tracks.some(t=>t[0]===selected))selected='original';music.src='./assets/'+tracks.find(t=>t[0]===selected)[2];
 $('musicChoices').innerHTML='<p><a href="./music-credits.html" target="_blank" rel="noopener">Müzik kaynakları ve kullanım izinleri</a></p><h3>Açılış müziğini seç</h3><p>Önce dinleyin, sonra istediğiniz müziği kullanın.</p>'+tracks.map(([id,name,file,duration],index)=>`${index===3?'<details><summary>Önceki müzik örnekleri</summary>':''}<article class="music-choice"><strong>${name} ${duration}</strong><audio controls preload="none" aria-label="${name} örneği" src="./assets/${file}"></audio><button class="secondary-button" data-music="${id}">${id===selected?'Seçili müzik':'Bu müziği kullan'}</button></article>${index===tracks.length-1?'</details>':''}`).join('');
 document.querySelectorAll('#musicChoices audio').forEach(a=>a.onplay=()=>{if(role!=='guardian'){a.pause();return;}music.pause();document.querySelectorAll('#musicChoices audio').forEach(other=>{if(other!==a)other.pause();});});
 document.querySelectorAll('[data-music]').forEach(b=>b.onclick=()=>{if(role!=='guardian')return;stopPreviews();selected=b.dataset.music;localStorage.setItem('specialEducationMusic',selected);music.src='./assets/'+tracks.find(t=>t[0]===selected)[2];document.querySelectorAll('[data-music]').forEach(button=>button.textContent=button.dataset.music===selected?'Seçili müzik':'Bu müziği kullan');});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&role==='guardian')lock();});window.addEventListener('pagehide',lock);sync();
})();
